import { NextResponse } from "next/server";
import { z } from "zod";

import { query } from "@/lib/db";

export const dynamic = "force-dynamic";

type RouteContext = {
  params: Promise<{
    id: string;
  }>;
};

type NoteRow = {
  id: string;
  title: string;
  type: "note" | "checklist" | "idea";
  content: string | null;
  color: string | null;
  created_at: string;
  updated_at: string;
  checklist_items: unknown[] | null;
  tags: string[] | null;
};

const updateNoteSchema = z
  .object({
    title: z.string().trim().min(3, "El título debe tener al menos 3 caracteres").optional(),
    content: z.string().trim().optional(),
    color: z.string().trim().min(1).optional(),
    tags: z.array(z.string().trim().min(1)).optional(),
  })
  .refine(
    (value) =>
      value.title !== undefined ||
      value.content !== undefined ||
      value.color !== undefined ||
      value.tags !== undefined,
    {
      message: "Debes enviar al menos un campo para actualizar.",
    },
  );

const noteByIdQuery = `
  SELECT
    n.id,
    n.title,
    n.type,
    n.content,
    n.color,
    n.created_at,
    n.updated_at,
    COALESCE(
      json_agg(
        DISTINCT jsonb_build_object(
          'id', ci.id,
          'text', ci.text,
          'isCompleted', ci.is_completed,
          'createdAt', ci.created_at,
          'updatedAt', ci.updated_at
        )
      ) FILTER (WHERE ci.id IS NOT NULL),
      '[]'::json
    ) AS checklist_items,
    COALESCE(
      json_agg(DISTINCT nt.tag) FILTER (WHERE nt.id IS NOT NULL),
      '[]'::json
    ) AS tags
  FROM notes AS n
  LEFT JOIN checklist_items AS ci
    ON ci.note_id = n.id
  LEFT JOIN note_tags AS nt
    ON nt.note_id = n.id
  WHERE n.id = $1
  GROUP BY n.id
`;

function mapNote(row: NoteRow) {
  return {
    id: row.id,
    title: row.title,
    type: row.type,
    content: row.content,
    color: row.color,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    checklistItems: row.checklist_items ?? [],
    tags: row.tags ?? [],
  };
}

export async function GET(_request: Request, context: RouteContext) {
  try {
    const { id } = await context.params;
    const rows = await query<NoteRow>(noteByIdQuery, [id]);

    if (rows.length === 0) {
      return NextResponse.json({ error: "Nota no encontrada" }, { status: 404 });
    }

    return NextResponse.json(mapNote(rows[0]));
  } catch {
    return NextResponse.json({ error: "Error interno" }, { status: 500 });
  }
}

export async function PATCH(request: Request, context: RouteContext) {
  try {
    const { id } = await context.params;
    const body = await request.json();
    const result = updateNoteSchema.safeParse(body);

    if (!result.success) {
      return NextResponse.json(
        {
          error: "Datos no válidos",
          details: result.error.flatten().fieldErrors,
        },
        { status: 400 },
      );
    }

    const { title, content, color, tags } = result.data;
    const rows = await query<{
      id: string;
      title: string;
      type: "note" | "checklist" | "idea";
      content: string | null;
      color: string | null;
      created_at: string;
      updated_at: string;
    }>(
      `
        UPDATE notes
        SET
          title = COALESCE($1, title),
          content = COALESCE($2, content),
          color = COALESCE($3, color),
          updated_at = NOW()
        WHERE id = $4
        RETURNING id, title, type, content, color, created_at, updated_at
      `,
      [title ?? null, content ?? null, color ?? null, id],
    );

    if (rows.length === 0) {
      return NextResponse.json({ error: "Nota no encontrada" }, { status: 404 });
    }

    const updated = rows[0];

    if (tags !== undefined) {
      await query(
        `
          DELETE FROM note_tags
          WHERE note_id = $1
        `,
        [id],
      );

      if (tags.length > 0) {
        await Promise.all(
          tags.map((tag) =>
            query(
              `
                INSERT INTO note_tags (note_id, tag)
                VALUES ($1, $2)
              `,
              [id, tag],
            ),
          ),
        );
      }
    }

    return NextResponse.json({
      id: updated.id,
      title: updated.title,
      type: updated.type,
      content: updated.content,
      color: updated.color,
      createdAt: updated.created_at,
      updatedAt: updated.updated_at,
      tags: tags ?? [],
    });
  } catch {
    return NextResponse.json({ error: "Error interno" }, { status: 500 });
  }
}

export async function DELETE(_request: Request, context: RouteContext) {
  try {
    const { id } = await context.params;
    const rows = await query<{ id: string }>(
      `
        DELETE FROM notes
        WHERE id = $1
        RETURNING id
      `,
      [id],
    );

    if (rows.length === 0) {
      return NextResponse.json({ error: "Nota no encontrada" }, { status: 404 });
    }

    return new NextResponse(null, { status: 204 });
  } catch {
    return NextResponse.json({ error: "Error interno" }, { status: 500 });
  }
}
